#!/usr/bin/env python3
"""Generate sw/dwconv5_asm.c (hand scalar, row-wise sliding accumulation) and
sw/dwconv5_simd_asm.c (hand cv.dotsp.b, unaligned loads) for K = 5, each with
RV32IMC control (XPULP_CTRL=0) and Xpulp control (XPULP_CTRL=1).
Run from the repository root: python3 sw/gen_dwconv5_asm.py"""
K = 5
HDR = '''/* Depthwise 5x5 -- hand-written {kind} inner loops. Generated by
 * sw/gen_dwconv5_asm.py; do not edit by hand.
 *
 * {desc}
 * XPULP_CTRL=0: RV32IMC control. XPULP_CTRL=1: hardware loops, post-increment
 * loads and stores. Requantisation from requant.h in both.
 */
#include "dw_common.h"
#include "xpulp.h"
#ifndef XPULP_CTRL
#define XPULP_CTRL 0
#endif
#if K != 5
#error "generated for K == 5"
#endif
#define XS(x) S_(x)
#define S_(x) #x
'''
def asm_block(xp, setup, body, nbody, loopctl, outs, ins):
    return f'''            asm volatile (
              {"XPULP_ASM_BEGIN" if xp else ""}
              {setup}
              {f'HWLOOP0("%[cnt]", RQ_XS({nbody}+1))   /* body: {nbody} instructions */' if xp else '"1:\\n"'}
              {body}
              {"" if xp else loopctl}
              {"XPULP_ASM_END" if xp else ""}
              : {outs}
              : {ins}
              : "memory");
'''
# ---------------- scalar: row-wise sliding accumulation ----------------
# For each output row: zero an int32 accumulator row, then for each of the 5
# kernel rows hold that row's 5 weights in registers and sweep the row with a
# 5-wide sliding window (one new byte load per pixel, 4 register moves), adding
# the 5-tap sum into the accumulator row; finally requantise the row.
def scalar_row_body(xp, first=False):
    L = []
    L.append('LB_INC("%[x4]", "%[r]", "1")' if xp else '"lb %[x4],4(%[r])\\n"')
    L.append('"mul %[t],%[x0],%[w0]\\n mul %[acc],%[x1],%[w1]\\n add %[acc],%[acc],%[t]\\n"')
    for i in (2, 3, 4): L.append(f'"mul %[t],%[x{i}],%[w{i}]\\n add %[acc],%[acc],%[t]\\n"')
    if not first: L.append('"lw %[t],0(%[ap])\\n add %[acc],%[acc],%[t]\\n"')
    L.append('SW_INC("%[acc]", "%[ap]", "4")' if xp else '"sw %[acc],0(%[ap])\\n"')
    L.append('"mv %[x0],%[x1]\\n mv %[x1],%[x2]\\n mv %[x2],%[x3]\\n mv %[x3],%[x4]\\n"')
    return "\n              ".join(L), 1 + 9 + (1 if first else 3) + 4
def scalar_rq_body(xp):
    L = ['LW_INC("%[acc]", "%[ap]", "4")' if xp else '"lw %[acc],0(%[ap])\\n"', 'REQUANT_ASM("%[acc]", "%[t]", "%[u]")',
         'SB_INC("%[acc]", "%[op]", "1")' if xp else '"sb %[acc],0(%[op])\\n"']
    return "\n              ".join(L), "2+RQ_N"
s = HDR.format(kind="scalar", desc="Row-wise sliding accumulation: per output row, for each of the 5 kernel rows\n * the 5 weights sit in registers and the row is swept with a 5-wide sliding\n * window (one byte load per pixel, four register moves, five multiplies); the\n * first kernel row stores the 5-tap sums into an int32 accumulator row, the\n * other four read-modify-write it; the row is then requantised. Loads per\n * pixel: 5 bytes + 4 accumulator words.")
s += '''
static void dwconv5_asm(void) {
    int accrow[OW];
    for (int c = 0; c < CH; c++) {
        const signed char *wp = &weight[c][0][0];
        signed char *op = &output[c][0][0];
        for (int oy = 0; oy < OH; oy++) {
            for (int ky = 0; ky < K; ky++) {
                const signed char *r = &input[c][oy + ky][0];
                int *ap = accrow;
                int w0 = wp[ky*K+0], w1 = wp[ky*K+1], w2 = wp[ky*K+2], w3 = wp[ky*K+3], w4 = wp[ky*K+4];
                int x0, x1, x2, x3, x4, acc, t;
'''
for xp in (1, 0):
    setup = ('"lb %[x0],-4(%[r])\\n lb %[x1],-3(%[r])\\n lb %[x2],-2(%[r])\\n lb %[x3],-1(%[r])\\n"' if xp
             else '"lb %[x0],0(%[r])\\n lb %[x1],1(%[r])\\n lb %[x2],2(%[r])\\n lb %[x3],3(%[r])\\n"')
    pre = ("                r += 4; int cnt = OW;\n" if xp else "                const signed char *rend = r + OW;\n")
    outs = '[r]"+r"(r), [ap]"+r"(ap), [acc]"=&r"(acc), [t]"=&r"(t), [x0]"=&r"(x0), [x1]"=&r"(x1), [x2]"=&r"(x2), [x3]"=&r"(x3), [x4]"=&r"(x4)'
    ins = ('[cnt]"r"(cnt), ' if xp else '[rend]"r"(rend), ') + '[w0]"r"(w0), [w1]"r"(w1), [w2]"r"(w2), [w3]"r"(w3), [w4]"r"(w4)'
    ctl = '"addi %[r],%[r],1\\n addi %[ap],%[ap],4\\n bne %[r],%[rend],1b\\n"'
    body0, n0 = scalar_row_body(xp, first=True); body1, n1 = scalar_row_body(xp)
    s += f"#if XPULP_CTRL == {xp}\n{pre}                if (ky == 0) {{\n" + asm_block(xp, setup, body0, n0, ctl, outs, ins) + "                } else {\n" + asm_block(xp, setup, body1, n1, ctl, outs, ins) + "                }\n#endif\n"
s += '''            }
            {   /* requantise the accumulator row */
                int *ap = accrow; int acc, t, u;
'''
for xp in (1, 0):
    body, n = scalar_rq_body(xp)
    pre = ("                int cnt = OW;\n" if xp else "                int *aend = accrow + OW;\n")
    outs = '[ap]"+r"(ap), [op]"+r"(op), [acc]"=&r"(acc), [t]"=&r"(t), [u]"=&r"(u)'
    ins = '[cnt]"r"(cnt)' if xp else '[aend]"r"(aend)'
    s += f"#if XPULP_CTRL == {xp}\n{pre}" + asm_block(xp, '', body, n, '"addi %[ap],%[ap],4\\n addi %[op],%[op],1\\n bne %[ap],%[aend],1b\\n"', outs, ins) + "#endif\n"
s += '''            }
        }
    }
}
int main(void) { BENCH_PAD(); init_data(); CYC_START(); dwconv5_asm(); CYC_STOP(); return checksum(); }
'''
open('sw/dwconv5_asm.c', 'w').write(s)
# ---------------- SIMD unaligned ----------------
# Per pixel: for each kernel row, two word loads at ox and ox+4 (lanes {a0..a3}
# and {a4,*,*,*}) against weight words {w0,w1,w2,w3} and {w4,0,0,0}; ten loads
# issued first, then one cv.dotsp.b and nine cv.sdotsp.b, requant, store.
def simd_body(xp):
    loads = []
    for ky in range(K):
        for half in (0, 1):
            off = ky * 'W' if False else None
            reg = f"%[l{ky}{half}]"
            if xp and ky == 0 and half == 0:
                loads.append('LW_INC("%[l00]", "%[p]", "1")')
            else:
                o = f"{ky}*W+{4*half}" + ("-1" if xp else "")
                loads.append(f'"lw {reg}," XS({o}) "(%[p])\\n"')
    ops = []
    first = True
    for ky in range(K):
        for half in (0, 1):
            w = f"%[w{'a' if half == 0 else 'b'}{ky}]"
            ops.append((f'DOTSP("%[acc]", "%[l{ky}{half}]", "{w}")' if first else f'SDOTSP("%[acc]", "%[l{ky}{half}]", "{w}")')); first = False
    L = loads + ops + ['REQUANT_ASM("%[acc]", "%[t]", "%[u]")', 'SB_INC("%[acc]", "%[op]", "1")' if xp else '"sb %[acc],0(%[op])\\n"']
    return "\n              ".join(L), "21+RQ_N"
s = HDR.format(kind="cv.dotsp.b, unaligned loads", desc="Per pixel and kernel row, two word loads at ox and ox+4 carry taps 0..3 and\n * tap 4 (other lanes meet zero weights); ten loads are issued first, then one\n * cv.dotsp.b and nine accumulating cv.sdotsp.b, requant, store. Three of\n * every four loads are misaligned at W=16.")
s += '''#define DOTSP(rd, rs1, rs2)  ".insn r 0x7b, 0x1, 0x48, " rd ", " rs1 ", " rs2 "\\n"
#define SDOTSP(rd, rs1, rs2) ".insn r 0x7b, 0x1, 0x54, " rd ", " rs1 ", " rs2 "\\n"
static inline unsigned int pack4(int a, int b, int c, int d) {
    return ((unsigned)(a & 0xFF)) | ((unsigned)(b & 0xFF) << 8) | ((unsigned)(c & 0xFF) << 16) | ((unsigned)(d & 0xFF) << 24);
}
static void dwconv5_simd_asm(void) {
    for (int c = 0; c < CH; c++) {
        const signed char *wp = &weight[c][0][0];
        unsigned int wa0 = pack4(wp[0], wp[1], wp[2], wp[3]),   wb0 = pack4(wp[4], 0, 0, 0);
        unsigned int wa1 = pack4(wp[5], wp[6], wp[7], wp[8]),   wb1 = pack4(wp[9], 0, 0, 0);
        unsigned int wa2 = pack4(wp[10], wp[11], wp[12], wp[13]), wb2 = pack4(wp[14], 0, 0, 0);
        unsigned int wa3 = pack4(wp[15], wp[16], wp[17], wp[18]), wb3 = pack4(wp[19], 0, 0, 0);
        unsigned int wa4 = pack4(wp[20], wp[21], wp[22], wp[23]), wb4 = pack4(wp[24], 0, 0, 0);
        signed char *op = &output[c][0][0];
        for (int oy = 0; oy < OH; oy++) {
            const signed char *p = &input[c][oy][0];
            unsigned int l00, l01, l10, l11, l20, l21, l30, l31, l40, l41; int acc, t, u;
'''
louts = ", ".join(f'[l{ky}{h}]"=&r"(l{ky}{h})' for ky in range(K) for h in (0, 1))
wins = ", ".join(f'[wa{ky}]"r"(wa{ky}), [wb{ky}]"r"(wb{ky})' for ky in range(K))
for xp in (1, 0):
    body, n = simd_body(xp)
    pre = ("            int cnt = OW;\n" if xp else "            const signed char *pend = p + OW;\n")
    outs = f'[p]"+r"(p), [op]"+r"(op), [acc]"=&r"(acc), [t]"=&r"(t), [u]"=&r"(u),\n                {louts}'
    ins = ('[cnt]"r"(cnt), ' if xp else '[pend]"r"(pend), ') + wins
    s += f"#if XPULP_CTRL == {xp}\n{pre}" + asm_block(xp, '', body, n, '"addi %[p],%[p],1\\n addi %[op],%[op],1\\n bne %[p],%[pend],1b\\n"', outs, ins) + "#endif\n"
s += '''        }
    }
}
int main(void) { BENCH_PAD(); init_data(); CYC_START(); dwconv5_simd_asm(); CYC_STOP(); return checksum(); }
'''
open('sw/dwconv5_simd_asm.c', 'w').write(s)
print("wrote sw/dwconv5_asm.c sw/dwconv5_simd_asm.c")
